CREATE OR REPLACE FUNCTION panas_accounting_funding_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.intent_id,NEW.buyer_id,NEW.amount,NEW.memo,NEW.treasury_owner,NEW.treasury_token_account,NEW.created_at,NEW.expires_at) IS DISTINCT FROM ROW(OLD.intent_id,OLD.buyer_id,OLD.amount,OLD.memo,OLD.treasury_owner,OLD.treasury_token_account,OLD.created_at,OLD.expires_at) OR (OLD.funded_at IS NOT NULL AND ROW(NEW.signature,NEW.proof,NEW.funded_at) IS DISTINCT FROM ROW(OLD.signature,OLD.proof,OLD.funded_at)) THEN RAISE EXCEPTION 'Funding intent terms and confirmed evidence are immutable'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS panas_funding_immutable ON panas_accounting_devnet_funding;
CREATE TRIGGER panas_funding_immutable BEFORE UPDATE ON panas_accounting_devnet_funding FOR EACH ROW EXECUTE FUNCTION panas_accounting_funding_immutable();
